<template>
  <div v-if="state" class="app-shell">
    <header class="topbar">
      <div class="brand"><span class="day-mark">15</span><div><b>AI Challenge</b><small>Контролируемые переходы</small></div></div>
      <div class="topbar-title"><span class="eyebrow">ТЕМА УРОКА</span><h1>Управляемые переходы</h1></div>
      <div class="header-actions"><span class="profile-badge"><i>{{ state.active_profile.name.slice(0,1) }}</i>{{ state.active_profile.name }}</span><button class="ghost settings-button" @click="showSettings=true">⚙ <span>Память и профиль</span></button></div>
    </header>
    <nav class="phase-stepper" aria-label="Этап задачи"><div v-for="(phase,index) in phases" :key="phase.id" :class="{active:state.task.phase===phase.id,passed:phaseIndex(state.task.phase)>index}"><span>{{ index+1 }}</span><b>{{ phase.label }}</b></div></nav>

    <section ref="workspaceEl" class="workspace" :style="{ '--state-panel-width': `${statePanelWidth}px` }">
      <aside ref="lessonPanelEl" class="lesson-panel">
        <div><span class="eyebrow">СЦЕНАРИЙ ДИАЛОГА</span><h2>Поездка с друзьями в лес</h2><p>Рассказывайте агенту о поездке обычными словами. Он поможет составить план, пройти подготовку и ничего не пропустить.</p></div>
        <button v-for="item in agentPromptButtons" :key="item.id" class="full demo-action" :class="item.primary ? 'primary' : 'secondary'" :disabled="busy" @click="fillAgentPrompt(item.text)">{{ item.label }}</button>
        <p class="action-note">Каждая кнопка только предлагает следующую бытовую реплику. Вы можете изменить текст перед отправкой.</p>
        <ol class="lesson-steps"><li><span>1</span><div><b>Расскажите о поездке</b><small>Агент сам выделит задачу и предложит понятный план.</small></div></li><li><span>2</span><div><b>Попробуйте поторопиться</b><small>Переход не состоится, пока план не принят вами.</small></div></li><li><span>3</span><div><b>Согласитесь обычной фразой</b><small>Явно примите результат и попросите продолжить в одном сообщении.</small></div></li><li><span>4</span><div><b>Дойдите до выезда</b><small>Сделайте паузу, найдите проблему на проверке и устраните её.</small></div></li></ol>
      </aside>

      <main class="chat-panel">
        <header class="chat-header"><div><span class="eyebrow">ГЛАВНЫЙ МАРШРУТ</span><h2>Управление задачей через агента</h2></div><span class="session-count">{{ state.active_session.messages.length }} сообщений</span></header>
        <div ref="messagesEl" class="messages">
          <div v-if="!state.active_session.messages.length" class="empty-state"><span class="empty-icon">⇢</span><h2>Начните со сценария слева</h2><p>Пишите агенту обычными словами. Он сам поймёт, нужно ли сохранить результат, продолжить процесс или просто ответить.</p></div>
          <article v-for="message in state.active_session.messages" :key="message.id" class="message" :class="message.role"><div class="message-label">{{ message.role==='user' ? 'Вы' : state.active_profile.name }}</div><div v-if="message.role==='assistant'" class="bubble assistant-content" v-html="message.answer_html"></div><div v-else class="bubble">{{ message.content }}</div><section v-if="message.role==='assistant' && message.preview?.action" class="agent-action-card" :class="[message.preview.action.outcome,actionTone(message.preview.action)]"><header><span>{{ actionStatusLabel(message.preview.action) }}</span><code>#{{ message.preview.action.id }} · {{ message.preview.action.reason_code }}</code></header><h3>{{ actionLabel(message.preview.action.action) }}</h3><p>{{ message.preview.action.message || reasonLabel(message.preview.action.reason_code) }}</p><div class="action-revisions"><span>{{ phaseLabel(message.preview.action.phase_before) }} → {{ phaseLabel(message.preview.action.phase_after) }}</span><span>rev {{ message.preview.action.revision_before }} → {{ message.preview.action.revision_after }}</span></div><ul v-if="message.preview.action.unmet_requirements?.length"><li v-for="item in message.preview.action.unmet_requirements" :key="item.code">{{ item.message || requirementLabel(item.code) }}</li></ul><small v-if="isBlockerResult(message.preview.action)" class="blocker-note">Подтверждать нечего: задача остаётся на проверке до устранения проблемы.</small></section><section v-else-if="message.role==='assistant' && message.preview?.kind==='agent_turn'" class="agent-action-card neutral"><header><span>○ состояние без изменений</span></header><h3>{{ actionLabel('respond_without_action') }}</h3><p>Агент ответил на вопрос, не меняя процесс.</p></section><button v-if="message.preview" class="preview-link" @click="preview=message.preview">Контекст ответа ↗</button></article>
          <article v-if="busy" class="message assistant"><div class="message-label">{{ state.active_profile.name }}</div><div class="bubble typing"><i></i><i></i><i></i></div></article>
        </div>
        <div class="composer-wrap">
          <div v-if="error" class="error-banner">{{ error }}</div>
          <section v-if="pendingApprovals.length" class="pending-tray"><span class="eyebrow">ОЖИДАЕТ ВАШЕГО РЕШЕНИЯ</span><article v-for="approval in pendingApprovals" :key="approval.id" class="pending-card"><div><b>{{ approvalLabel(approval.kind) }}</b><span>{{ approval.display_summary }}</span><small>Можно явно согласиться в сообщении и попросить продолжить. Кнопки справа — безопасный ручной вариант.</small><small>{{ phaseLabel(approval.expected_phase) }} · ожидаемая rev {{ approval.expected_revision }}</small></div><div><button class="secondary" :disabled="busy" @click="resolveApproval(approval,'reject')">Отклонить</button><button class="primary" :disabled="busy" @click="resolveApproval(approval,'confirm')">Подтвердить</button></div></article></section>
          <div v-if="state.task.run_status==='paused'" class="state-banner paused"><b>Задача на паузе</b><span>Чат остаётся доступным: попросите агента продолжить задачу.</span></div>
          <div v-else-if="state.task.phase==='done'" class="state-banner done"><b>Задача завершена</b><span>Можно попросить агента объяснить итог; lifecycle остаётся только для чтения.</span></div>
          <form class="composer" @submit.prevent="send"><textarea ref="composerEl" :value="prompt" rows="7" maxlength="4000" :placeholder="state.task.run_status==='paused' ? 'Попросите продолжить задачу…' : state.task.phase==='done' ? 'Попросите объяснить итог…' : 'Напишите агенту обычную реплику…'" @input="handlePromptInput" @keydown.enter.exact.prevent="send"></textarea><button class="send" :disabled="busy || !canSend" aria-label="Отправить агенту">↑</button></form><small>Одно сообщение — одно безопасное изменение или обычный ответ. Решение о согласии всегда остаётся за вами.</small>
        </div>
      </main>

      <div
        ref="resizeHandleEl"
        class="resize-handle"
        :class="{ dragging: isResizing }"
        role="separator"
        aria-orientation="vertical"
        aria-label="Изменить ширину панели состояния"
        :aria-valuemin="panelWidthMin"
        :aria-valuemax="panelWidthMax"
        :aria-valuenow="statePanelWidth"
        tabindex="0"
        @pointerdown="startPanelResize"
        @pointermove="resizePanel"
        @pointerup="finishPanelResize"
        @pointercancel="finishPanelResize"
        @lostpointercapture="finishPanelResize"
        @keydown="resizePanelByKeyboard"
        @dblclick="resetPanelWidth"
      ><span aria-hidden="true"></span></div>

      <aside class="state-panel">
        <section class="editor-card evidence-card"><div class="panel-heading"><div><span class="eyebrow">AUTHORITATIVE STATE</span><h2>{{ phaseLabel(state.task.phase) }} · ревизия {{ state.task.revision }}</h2></div><span class="machine-status" :class="state.task.run_status">{{ state.task.run_status==='paused' ? 'пауза' : state.task.phase==='done' ? 'готово' : 'активно' }}</span></div><div class="evidence-overview"><article><b>План подготовки</b><p>{{ state.task.plan_artifact || 'Не сохранён' }}</p><span :class="{ready:state.task.planning_ready}">{{ planningReadinessLabel }}</span><span :class="{ready:state.task.plan_approved}">{{ state.task.plan_approved ? '✓ подтверждён человеком' : state.task.planning_ready ? '○ ожидает подтверждения' : '○ подтверждение пока недоступно' }}</span></article><article><b>Результат сборов</b><p>{{ state.task.execution_result || 'Не сохранён' }}</p><span :class="{ready:state.task.implementation_ready}">{{ state.task.implementation_ready ? '✓ готовность подтверждена' : '○ готовность не подтверждена' }}</span></article><article><b>Блокирующие замечания</b><p>{{ state.task.blocking_issues || 'Нет сохранённых замечаний' }}</p><span :class="{ready:state.task.validation_passed}">{{ state.task.validation_passed ? '✓ проверка подтверждена' : '○ проверка не подтверждена' }}</span></article></div></section>
        <section class="editor-card guard-card"><div class="panel-heading"><div><span class="eyebrow">СЕРВЕРНЫЕ GUARDS</span><h2>Что разрешено сейчас</h2></div></div><div class="guard-options"><div v-for="option in state.transition_options" :key="option.event" :class="{blocked:!option.enabled}"><div><b>{{ eventLabel(option.event) }} → {{ phaseLabel(option.target) }}</b><small v-if="option.unmet_requirements.length">Не выполнено: {{ option.unmet_requirements.map(item=>item.message).join(' ') }}</small><small v-else>Все обязательные условия выполнены.</small></div><span class="guard-verdict" :class="{ready:option.enabled}">{{ option.enabled ? 'разрешён' : 'заблокирован' }}</span></div></div></section>
        <section class="editor-card attempt-card"><span class="eyebrow">БЕЗОПАСНЫЙ ЖУРНАЛ ПОПЫТОК</span><h2>Принятые и отклонённые</h2><div class="attempt-list"><div v-for="attempt in state.task_transition_attempts.slice(0,8)" :key="attempt.id" :class="attempt.outcome"><b>{{ attempt.outcome==='accepted' ? '✓ принято' : '× отклонено' }} · {{ eventLabel(attempt.event) }} → {{ phaseLabel(attempt.requested_target) }}</b><span>{{ reasonLabel(attempt.reason_code) }}</span><small v-if="attempt.reason_code==='invalid_target'">Запрошен этап: {{ phaseLabel(attempt.requested_target) }}. Фактический этап не изменён: {{ phaseLabel(attempt.from_phase) }}.</small><small v-if="attempt.unmet_requirements.length">{{ attempt.unmet_requirements.map(item=>item.message || requirementLabel(item.code)).join(' ') }}</small><small>ожидалась ревизия {{ attempt.expected_revision }} · фактическая {{ attempt.actual_revision }}</small><code>{{ attempt.reason_code }}</code></div><p v-if="!state.task_transition_attempts.length" class="hint">Попыток пока нет.</p></div></section>
        <section class="editor-card agent-audit-card"><span class="eyebrow">ДЕЙСТВИЯ АГЕНТА</span><h2>Последние server actions</h2><div class="agent-audit-list"><article v-for="action in state.agent_actions.slice(0,6)" :key="action.id" :class="[action.outcome,actionTone(action)]"><b>{{ actionStatusLabel(action) }} {{ actionLabel(action.action) }}</b><span>{{ isBlockerResult(action) ? 'Найдена блокирующая проблема: переход не выполнен.' : reasonLabel(action.reason_code) }}</span><small>{{ phaseLabel(action.phase_before) }} → {{ phaseLabel(action.phase_after) }} · rev {{ action.revision_before }} → {{ action.revision_after }}</small><code>{{ action.reason_code }}</code></article><p v-if="!state.agent_actions.length" class="hint">Агент ещё не запрашивал действий.</p></div></section>
        <section class="editor-card task-card"><span class="eyebrow">КОНТЕКСТ И КОНТРОЛЬНАЯ ТОЧКА</span><h2>{{ state.task.goal || 'Задача ещё не определена' }}</h2><div class="checkpoint-grid"><div><span>Текущий шаг</span><b>{{ state.task.current_step || 'Не указан' }}</b></div><div><span>Ожидаемое действие</span><b>{{ state.task.expected_action || 'Не указано' }}</b></div></div></section>
        <details class="editor-card diagnostic-card"><summary><span><b>Ручная диагностика</b><small>Прямые формы для проверки API, не основной сценарий.</small></span><i>⌄</i></summary><div class="diagnostic-content"><form class="stack-form" @submit.prevent="saveTask"><h3>Задача и checkpoint</h3><fieldset :disabled="taskLocked"><label>Цель<input v-model="taskForm.goal" maxlength="500"></label><label>Жёсткие ограничения<textarea v-model="taskForm.hard_constraints" maxlength="500" rows="2"></textarea></label><label>Исходные данные<textarea v-model="taskForm.task_data" maxlength="500" rows="2"></textarea></label><label>Открытые вопросы<textarea v-model="taskForm.open_questions" maxlength="500" rows="2"></textarea></label><label>Текущий шаг<input v-model="taskForm.current_step" maxlength="500"></label><label>Ожидаемое действие<textarea v-model="taskForm.expected_action" maxlength="500" rows="2"></textarea></label></fieldset><button class="secondary full" :disabled="busy || taskLocked || !taskForm.goal.trim()">Сохранить задачу вручную</button></form><form class="stack-form" @submit.prevent="saveEvidence"><h3>Evidence и approvals</h3><label>План подготовки<textarea v-model="evidenceForm.plan_artifact" rows="3" maxlength="2000" :disabled="taskLocked || state.task.phase!=='planning'"></textarea></label><button v-if="state.task.phase==='planning'" type="button" class="secondary full" :disabled="busy || taskLocked || !state.task.plan_artifact" @click="decideEvidence('plan_approved')">Подтвердить план вручную</button><label>Результат сборов<textarea v-model="evidenceForm.execution_result" rows="3" maxlength="2000" :disabled="taskLocked || state.task.phase!=='execution'"></textarea></label><button v-if="state.task.phase==='execution'" type="button" class="secondary full" :disabled="busy || taskLocked || !state.task.execution_result" @click="decideEvidence('implementation_ready')">Подтвердить готовность вручную</button><label>Блокирующие замечания<textarea v-model="evidenceForm.blocking_issues" rows="2" maxlength="1000" :disabled="taskLocked || state.task.phase!=='validation'"></textarea></label><button v-if="state.task.phase==='validation'" type="button" class="secondary full" :disabled="busy || taskLocked || !!state.task.blocking_issues" @click="decideEvidence('validation_passed')">Проблем нет — подтвердить проверку вручную</button><button class="secondary full" :disabled="busy || taskLocked">Сохранить evidence вручную</button></form><section><h3>Переход</h3><div class="guard-options"><div v-for="option in state.transition_options" :key="option.event" :class="{blocked:!option.enabled}"><div><b>{{ eventLabel(option.event) }} → {{ phaseLabel(option.target) }}</b><small v-if="option.unmet_requirements.length">{{ option.unmet_requirements.map(item=>item.message).join(' ') }}</small></div><button v-if="['pause','resume'].includes(option.event)" class="secondary" :disabled="busy" @click="transitionTask(option.event,option.target)">{{ eventLabel(option.event) }}</button><button v-else class="secondary" :disabled="busy" @click="fillTransition(option.event,option.target)">Подготовить</button></div></div><form v-if="transitionDraft.event" class="stack-form transition-draft" @submit.prevent="confirmTransition"><div class="transition-summary"><span>Событие</span><b>{{ eventLabel(transitionDraft.event) }}</b><span>Целевой этап</span><b>{{ phaseLabel(transitionDraft.target) }}</b></div><label>Следующий шаг<input v-model="transitionDraft.next_current_step" maxlength="500"></label><label>Ожидаемое действие<textarea v-model="transitionDraft.next_expected_action" maxlength="500" rows="2"></textarea></label><button class="primary full" :disabled="busy">Попробовать переход вручную</button></form></section></div></details>
      </aside>
    </section>

    <div v-if="showCreate" class="modal-backdrop" @click.self="showCreate=false"><section class="modal"><button class="modal-close" @click="showCreate=false">×</button><span class="eyebrow">НОВЫЙ ПРОФИЛЬ</span><h2>Создать профиль ответа</h2><p class="modal-lead">Четыре встроенных профиля уже доступны. Здесь можно создать собственный режим без автозаполнения.</p><form class="stack-form" @submit.prevent="createProfile"><label>Название<input v-model="createForm.name" maxlength="80" required></label><label>Роль и контекст<textarea v-model="createForm.role_context" maxlength="500" rows="2"></textarea></label><div class="triple"><label>Тон<select v-model="createForm.tone"><option value="friendly">Дружелюбный</option><option value="neutral">Нейтральный</option><option value="business">Деловой</option></select></label><label>Глубина<select v-model="createForm.detail_level"><option value="brief">Кратко</option><option value="balanced">Баланс</option><option value="deep">Глубоко</option></select></label><label>Формат<select v-model="createForm.response_format"><option value="paragraphs">Абзацы</option><option value="bullets">Список</option><option value="steps">Шаги</option><option value="table">Таблица</option></select></label></div><label>Язык<input v-model="createForm.language" maxlength="500"></label><label>Ограничения<textarea v-model="createForm.constraints" maxlength="500" rows="2"></textarea></label><button class="primary full">Создать и активировать</button></form></section></div>

    <div v-if="showSettings" class="modal-backdrop" @click.self="showSettings=false"><section class="modal settings-modal"><button class="modal-close" @click="showSettings=false">×</button><span class="eyebrow">СКРЫТО ОТ ГЛАВНОГО УРОКА</span><h2>Память и профиль</h2><div class="settings-tabs"><button v-for="tab in settingsTabs" :key="tab.id" :class="{active:settingsTab===tab.id}" @click="settingsTab=tab.id">{{ tab.label }}</button></div>
      <div v-if="settingsTab==='profiles'" class="settings-content"><div class="settings-heading"><div><h3>Профили ответа</h3><p>Выберите режим ответа или настройте активный профиль.</p></div><button class="secondary" @click="openCreateProfile">＋ Новый</button></div><div class="profile-list light"><button v-for="profile in state.profiles" :key="profile.id" class="profile-item" :class="{active:profile.id===state.active_profile.id}" :disabled="busy" @click="activateProfile(profile.id)"><span class="avatar">{{ profile.name.slice(0,1) }}</span><span><b>{{ profile.name }}</b><small>{{ toneLabel(profile.tone) }} · {{ detailLabel(profile.detail_level) }}</small></span><i v-if="profile.is_active">●</i></button></div><form class="stack-form settings-form" @submit.prevent="saveProfile"><label>Название<input v-model="profileForm.name" maxlength="80"></label><label>Роль и контекст<textarea v-model="profileForm.role_context" maxlength="500" rows="2"></textarea></label><div class="triple"><label>Тон<select v-model="profileForm.tone"><option value="friendly">Дружелюбный</option><option value="neutral">Нейтральный</option><option value="business">Деловой</option></select></label><label>Глубина<select v-model="profileForm.detail_level"><option value="brief">Кратко</option><option value="balanced">Баланс</option><option value="deep">Глубоко</option></select></label><label>Формат<select v-model="profileForm.response_format"><option value="paragraphs">Абзацы</option><option value="bullets">Список</option><option value="steps">Шаги</option><option value="table">Таблица</option></select></label></div><label>Язык<input v-model="profileForm.language" maxlength="500"></label><label>Ограничения<textarea v-model="profileForm.constraints" maxlength="500" rows="2"></textarea></label><button class="primary">Сохранить профиль</button></form></div>
      <div v-if="settingsTab==='sessions'" class="settings-content"><div class="settings-heading"><div><h3>Диалоги</h3><p>Диалоги принадлежат активному профилю.</p></div><button class="primary" :disabled="busy" @click="createSession">＋ Новый</button></div><div class="session-list light"><div v-for="session in state.sessions" :key="session.id" class="session-row" :class="{active:session.is_active}"><button class="session-activate" :disabled="busy" @click="activateSession(session.id)"><span>{{ session.branched_from_id ? '⑂' : '◌' }}</span><span><b>{{ session.label }}</b><small>{{ session.message_count }} сообщений</small></span></button><button class="session-delete" :disabled="busy" @click.stop="deleteSession(session)">×</button></div></div><div class="dialog-actions"><button class="secondary" :disabled="busy" @click="branchSession">⑂ Создать ветку</button><button class="danger-button" :disabled="busy" @click="resetSession">Очистить чат</button></div></div>
      <div v-if="settingsTab==='memory'" class="settings-content"><h3>Долговременная память</h3><p>Явные решения и знания доступны всем профилям.</p><div class="memory-items"><div v-for="item in state.long_term" :key="item.id" class="memory-item"><span>{{ item.entry_type==='decision' ? 'Решение' : 'Знание' }}</span><p>{{ item.content }}</p><button :disabled="busy" @click="deleteLongTerm(item.id)">×</button></div><p v-if="!state.long_term.length" class="hint">Записей пока нет.</p></div><form class="inline-add" @submit.prevent="addLongTerm"><select v-model="memoryType"><option value="knowledge">Знание</option><option value="decision">Решение</option></select><input v-model="memoryText" maxlength="500" placeholder="Добавить явную запись"><button :disabled="busy || !memoryText.trim()">＋</button></form></div>
      <div v-if="settingsTab==='model'" class="settings-content"><h3>Модель и контекст</h3><form class="stack-form" @submit.prevent="showSettings=false"><div class="double"><label>Провайдер<select v-model="controls.provider"><option value="deepseek">DeepSeek</option><option value="openrouter">OpenRouter</option></select></label><label>Модель<select v-model="controls.model"><template v-if="controls.provider==='deepseek'"><option value="deepseek-flash">DeepSeek Flash</option><option value="deepseek-v4-pro">DeepSeek V4 Pro</option></template><option v-else value="openrouter/free">OpenRouter Free</option></select></label></div><label>Режим памяти<select v-model="controls.compression_mode"><option value="full_session">Полная сессия</option><option value="sliding_window">Sliding Window</option><option value="sticky_facts">Sticky Facts</option><option value="rolling_summary">Rolling summary</option><option value="explicit_only">Только явная память</option></select></label><label v-if="['sliding_window','sticky_facts'].includes(controls.compression_mode)">Размер окна<input v-model.number="controls.window_size" type="number" min="2" max="20" step="2"></label><div v-if="controls.compression_mode==='rolling_summary'" class="double"><label>Batch<input v-model.number="controls.batch_size" type="number" min="2" max="20" step="2"></label><label>Оставить<input v-model.number="controls.keep_recent" type="number" min="2" max="20" step="2"></label></div><div class="double"><label>Temperature<input v-model.number="controls.temperature" type="number" min="0" max="2" step="0.1"></label><label>Max tokens<input v-model="controls.max_tokens" type="number" min="1" max="4096" placeholder="По умолчанию"></label></div><button class="primary">Готово</button></form><section class="danger-zone"><span class="eyebrow">ОПАСНАЯ ЗОНА</span><h3>Удалить все данные</h3><p>Будут удалены диалоги, память, состояние задачи и журналы. Встроенные профили будут восстановлены, «Обычный» станет активным, ID начнутся заново.</p><button class="danger-button full" :disabled="busy" @click="clearAll">Удалить всё и начать заново</button></section></div>
    </section></div>
    <div v-if="preview" class="modal-backdrop" @click.self="preview=null"><section class="modal preview-modal"><button class="modal-close" @click="preview=null">×</button><span class="eyebrow">ТОЧНЫЙ SNAPSHOT</span><h2>Контекст ответа</h2><div class="snapshot"><b>{{ preview.profile_snapshot?.name }}</b><span>{{ preview.profile_snapshot?.tone }} · {{ preview.profile_snapshot?.detail_level }} · {{ preview.profile_snapshot?.response_format }}</span></div><pre>{{ JSON.stringify(preview, null, 2) }}</pre></section></div>
  </div>
  <div v-else class="loading">Загружаем агент с конечным автоматом…</div>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { agentPrompts, lifecycleDemo } from './demo-presets'
const state=ref(null),prompt=ref(''),busy=ref(false),error=ref(''),messagesEl=ref(null),composerEl=ref(null)
const pendingAskRetry=ref(null)
const workspaceEl=ref(null),lessonPanelEl=ref(null),resizeHandleEl=ref(null)
const PANEL_STORAGE_KEY='day15.statePanelWidth',PANEL_DEFAULT=440,PANEL_MIN=300,PANEL_MAX=640,CHAT_MIN=480,RESIZE_STEP=24
const statePanelWidth=ref(PANEL_DEFAULT),panelWidthMin=ref(PANEL_MIN),panelWidthMax=ref(PANEL_MAX),isResizing=ref(false)
let resizePointerId=null,resizeStartX=0,resizeStartWidth=PANEL_DEFAULT
const showCreate=ref(false),showSettings=ref(false),preview=ref(null),settingsTab=ref('profiles')
const memoryType=ref('knowledge'),memoryText=ref('')
const settingsTabs=[{id:'profiles',label:'Профили'},{id:'sessions',label:'Диалоги'},{id:'memory',label:'Память'},{id:'model',label:'Модель'}]
const blankProfile={name:'',role_context:'',language:'Русский',tone:'neutral',detail_level:'balanced',response_format:'paragraphs',constraints:''}
const createForm=reactive({...blankProfile}),profileForm=reactive({...blankProfile})
const taskForm=reactive({goal:'',hard_constraints:'',task_data:'',open_questions:'',current_step:'',expected_action:''})
const evidenceForm=reactive({plan_artifact:'',execution_result:'',blocking_issues:''})
const transitionDraft=reactive({event:'',target:'',next_current_step:'',next_expected_action:''})
const phases=[{id:'planning',label:'Планирование'},{id:'execution',label:'Выполнение'},{id:'validation',label:'Проверка'},{id:'done',label:'Готово'}]
const controls=reactive({provider:'deepseek',model:'deepseek-flash',temperature:0,max_tokens:'',compression_mode:'full_session',window_size:6,batch_size:10,keep_recent:6})
const taskLocked=computed(()=>state.value?.task.run_status==='paused'||state.value?.task.phase==='done')
const canSend=computed(()=>prompt.value.trim())
const pendingApprovals=computed(()=>{
  const task=state.value?.task
  return (state.value?.pending_agent_approvals||[]).filter(item=>
    item.status==='pending'&&item.expected_phase===task?.phase&&item.expected_revision===task?.revision
  )
})
const planningReadinessLabel=computed(()=>{
  const task=state.value?.task
  if(!task)return ''
  if(task.planning_ready)return '✓ план готов к подтверждению'
  const count=(task.open_questions||'').split(/[;\n]+/).filter(item=>item.trim()).length
  return count ? `○ нужно уточнить ${count} пункт(а)` : '○ план пока не готов'
})
const agentPromptButtons=computed(()=>{
  const task=state.value.task,items=[],pending=pendingApprovals.value[0]
  if(task.phase==='planning'&&task.run_status==='active'&&!task.goal){
    items.push({id:'define',label:'1. Рассказать о поездке',text:agentPrompts.defineTask,primary:true})
    items.push({id:'explain',label:'Задать обычный вопрос',text:agentPrompts.explain})
    return items
  }
  if(task.run_status==='paused'){
    items.push({id:'resume',label:'Продолжить подготовку',text:agentPrompts.resume,primary:true})
    items.push({id:'explain',label:'Напомнить, где остановились',text:agentPrompts.explain})
    return items
  }
  if(task.phase==='done'){
    items.push({id:'explain',label:'Подвести итог',text:agentPrompts.done,primary:true})
    return items
  }
  if(task.phase==='planning'){
    if(!task.planning_ready){
      items.push({id:'refine',label:'Уточнить план',text:agentPrompts.refinePlan,primary:true})
      items.push({id:'early',label:'Попробовать перейти раньше',text:agentPrompts.earlyTransition})
    }else if(pending?.kind==='plan_approved'){
      items.push({id:'early',label:'2. Попробовать без плана',text:agentPrompts.earlyTransition})
      items.push({id:'skip-validation',label:'Попробовать перейти к проверке',text:agentPrompts.skipToValidation})
      items.push({id:'accept',label:'3. Принять план и продолжить',text:agentPrompts.acceptPlan,primary:true})
    }else if(task.plan_approved)items.push({id:'advance',label:'Перейти к выполнению',text:agentPrompts.acceptPlan,primary:true})
    else items.push({id:'early',label:'2. Попробовать без плана',text:agentPrompts.earlyTransition})
  }
  if(task.phase==='execution'){
    if(pending?.kind==='implementation_ready')items.push({id:'accept',label:'Принять результат и проверить',text:agentPrompts.acceptExecution,primary:true})
    else if(task.implementation_ready)items.push({id:'advance',label:'Перейти к проверке',text:agentPrompts.acceptExecution,primary:true})
    else items.push({id:'result',label:'Рассказать, что уже собрано',text:agentPrompts.executionResult,primary:true})
  }
  if(task.phase==='validation'){
    if(pending?.kind==='validation_passed')items.push({id:'accept',label:'Подтвердить и завершить',text:agentPrompts.acceptValidation,primary:true})
    else if(task.validation_passed&&!task.blocking_issues)items.push({id:'advance',label:'Завершить подготовку',text:agentPrompts.acceptValidation,primary:true})
    else if(task.blocking_issues){
      items.push({id:'finish-blocked',label:'Попробовать закончить сейчас',text:agentPrompts.tryFinishBlocked})
      items.push({id:'clear',label:'Сообщить, что всё исправлено',text:agentPrompts.validationClear,primary:true})
    }else items.push({id:'blocker',label:'Сообщить о забытом паспорте',text:agentPrompts.validationBlocked,primary:true})
  }
  items.push({id:'pause',label:'Сделать паузу',text:agentPrompts.pause})
  items.push({id:'explain',label:'Спросить, что дальше',text:agentPrompts.explain})
  return items
})
function updatePanelBounds(){if(!workspaceEl.value||window.innerWidth<=900)return;const workspaceWidth=workspaceEl.value.getBoundingClientRect().width,lessonWidth=lessonPanelEl.value?.getBoundingClientRect().width||0,handleWidth=resizeHandleEl.value?.getBoundingClientRect().width||10,available=Math.max(0,workspaceWidth-lessonWidth-handleWidth),chatMinimum=Math.min(CHAT_MIN,Math.max(320,available-PANEL_MIN)),maximum=Math.max(0,Math.min(PANEL_MAX,available-chatMinimum)),minimum=Math.min(PANEL_MIN,maximum);panelWidthMin.value=Math.round(minimum);panelWidthMax.value=Math.round(maximum);statePanelWidth.value=Math.min(panelWidthMax.value,Math.max(panelWidthMin.value,statePanelWidth.value))}
function storePanelWidth(){try{localStorage.setItem(PANEL_STORAGE_KEY,String(Math.round(statePanelWidth.value)))}catch{ /* Layout remains usable when storage is unavailable. */ }}
function setPanelWidth(width,{persist=false}={}){updatePanelBounds();statePanelWidth.value=Math.min(panelWidthMax.value,Math.max(panelWidthMin.value,Math.round(width)));if(persist)storePanelWidth()}
function startPanelResize(event){if(event.button!==0||window.innerWidth<=900)return;resizePointerId=event.pointerId;resizeStartX=event.clientX;resizeStartWidth=statePanelWidth.value;isResizing.value=true;event.currentTarget.setPointerCapture(event.pointerId);document.body.classList.add('resizing-state-panel');event.preventDefault()}
function resizePanel(event){if(!isResizing.value||event.pointerId!==resizePointerId)return;setPanelWidth(resizeStartWidth-(event.clientX-resizeStartX))}
function finishPanelResize(event){if(!isResizing.value||event.pointerId!==resizePointerId)return;if(event.currentTarget.hasPointerCapture?.(event.pointerId))event.currentTarget.releasePointerCapture(event.pointerId);resizePointerId=null;isResizing.value=false;document.body.classList.remove('resizing-state-panel');storePanelWidth()}
function resizePanelByKeyboard(event){let width=statePanelWidth.value;if(event.key==='ArrowLeft')width+=RESIZE_STEP;else if(event.key==='ArrowRight')width-=RESIZE_STEP;else if(event.key==='Home')width=panelWidthMin.value;else if(event.key==='End')width=panelWidthMax.value;else return;event.preventDefault();setPanelWidth(width,{persist:true})}
function resetPanelWidth(){setPanelWidth(PANEL_DEFAULT,{persist:true})}
function handleViewportResize(){updatePanelBounds()}
async function api(path,options={}){error.value='';const response=await fetch(path,{headers:{'Content-Type':'application/json'},...options});const data=await response.json().catch(()=>({}));if(!response.ok){const issue=new Error(data.detail?.message||data.detail||'Не удалось выполнить запрос');issue.detail=data.detail;throw issue}return data}
function sync(next){state.value=next;Object.assign(profileForm,Object.fromEntries(Object.keys(blankProfile).map(key=>[key,next.active_profile[key]??''])));Object.assign(taskForm,Object.fromEntries(Object.keys(taskForm).map(key=>[key,next.task?.[key]??''])));Object.assign(evidenceForm,{plan_artifact:next.task.plan_artifact,execution_result:next.task.execution_result,blocking_issues:next.task.blocking_issues});nextTick(()=>{scrollBottom();updatePanelBounds()})}
function scrollBottom(){if(messagesEl.value)messagesEl.value.scrollTop=messagesEl.value.scrollHeight}
async function mutate(path,method='POST',body){busy.value=true;try{sync(await api(path,{method,body:body===undefined?undefined:JSON.stringify(body)}))}catch(e){error.value=e.message}finally{busy.value=false}}
const activateProfile=id=>mutate(`/api/profiles/${id}/activate`),createSession=()=>mutate('/api/sessions'),activateSession=id=>mutate(`/api/sessions/${id}/activate`),branchSession=()=>mutate(`/api/sessions/${state.value.active_session.id}/branch`)
async function resetSession(){if(confirm('Удалить историю этого диалога?'))await mutate(`/api/sessions/${state.value.active_session.id}/reset`)}
async function deleteSession(session){if(confirm(`Удалить диалог «${session.label}» вместе с его сообщениями?`))await mutate(`/api/sessions/${session.id}`,'DELETE')}
async function clearAll(){if(!confirm('Удалить диалоги, память, состояние задачи и журналы? Встроенные профили будут восстановлены. Это действие нельзя отменить.'))return;await mutate('/api/memory/clear');if(!error.value)showSettings.value=false}
async function saveProfile(){await mutate(`/api/profiles/${state.value.active_profile.id}`,'PUT',profileForm)}
async function createProfile(){await mutate('/api/profiles','POST',createForm);if(!error.value){showCreate.value=false;Object.assign(createForm,blankProfile)}}
function openCreateProfile(){showSettings.value=false;showCreate.value=true}
function updatePrompt(text){if(pendingAskRetry.value&&text!==pendingAskRetry.value.prompt)pendingAskRetry.value=null;prompt.value=text}
function handlePromptInput(event){updatePrompt(event.target.value)}
function fillAgentPrompt(text){updatePrompt(text);nextTick(()=>composerEl.value?.focus())}
async function saveTask(){await mutate('/api/task','PUT',taskForm)}
async function saveEvidence(){await mutate('/api/task/evidence','PUT',{...evidenceForm,expected_revision:state.value.task.revision})}
async function decideEvidence(kind){
  if(kind==='plan_approved'&&!state.value.task.planning_ready){
    error.value='Сначала закройте критичные вопросы и подготовьте исполнимый план.'
    return
  }
  await mutate('/api/task/evidence/decision','POST',{kind,value:true,expected_revision:state.value.task.revision})
}
function fillTransition(event,target){const draft=lifecycleDemo.checkpoints[target]||{current_step:state.value.task.current_step,expected_action:state.value.task.expected_action};Object.assign(transitionDraft,{event,target,next_current_step:draft.current_step,next_expected_action:draft.expected_action})}
async function requestTransition(payload){busy.value=true;let accepted=false;try{sync(await api('/api/task/transition',{method:'POST',body:JSON.stringify(payload)}));accepted=true}catch(e){const transitionError=e.message;if(e.detail?.category==='transition_rejected'){try{sync(await api('/api/state'))}catch{ /* Основной текст отказа важнее ошибки фоновой синхронизации. */ }}error.value=transitionError}finally{busy.value=false}return accepted}
async function confirmTransition(){const payload={...transitionDraft,expected_revision:state.value.task.revision};if(await requestTransition(payload))Object.assign(transitionDraft,{event:'',target:'',next_current_step:'',next_expected_action:''})}
async function transitionTask(event,target=state.value.task.phase){if(await requestTransition({event,target,expected_revision:state.value.task.revision}))Object.assign(transitionDraft,{event:'',target:'',next_current_step:'',next_expected_action:''})}
async function addLongTerm(){await mutate('/api/long-term','POST',{entry_type:memoryType.value,content:memoryText.value});if(!error.value)memoryText.value=''}
const deleteLongTerm=id=>mutate(`/api/long-term/${id}`,'DELETE')
async function resolveApproval(approval,decision){if(busy.value)return;busy.value=true;try{const result=await api(`/api/agent/approvals/${approval.id}/${decision}`,{method:'POST'});sync(result.state)}catch(e){const approvalError=e.message;try{sync(await api('/api/state'))}catch{ /* Preserve the approval error. */ }error.value=approvalError}finally{busy.value=false}}
async function send(){if(busy.value||!canSend.value)return;const question=prompt.value;const requestId=pendingAskRetry.value?.prompt===question?pendingAskRetry.value.requestId:crypto.randomUUID();pendingAskRetry.value={prompt:question,requestId};prompt.value='';busy.value=true;await nextTick();scrollBottom();try{const result=await api('/api/ask',{method:'POST',body:JSON.stringify({prompt:question,request_id:requestId,controls}),headers:{'Content-Type':'application/json'}});sync(result.state);pendingAskRetry.value=null}catch(e){prompt.value=question;error.value=e.message}finally{busy.value=false;await nextTick();scrollBottom()}}
const toneLabel=value=>({friendly:'дружелюбно',neutral:'нейтрально',business:'по-деловому'}[value]||value),detailLabel=value=>({brief:'кратко',balanced:'баланс',deep:'глубоко'}[value]||value),phaseLabel=value=>Object.fromEntries(phases.map(item=>[item.id,item.label]))[value]||value,phaseIndex=value=>phases.findIndex(item=>item.id===value),eventLabel=value=>({advance:'Следующий этап',approve:'Завершить',pause:'Поставить на паузу',resume:'Продолжить'}[value]||value)
const isBlockerResult=action=>action?.action==='record_validation_result'&&action?.outcome==='accepted'&&action?.safe_details?.has_blockers===true
const actionTone=action=>isBlockerResult(action)?'warning':''
const actionStatusLabel=action=>isBlockerResult(action)?'! найдена проблема':action?.outcome==='accepted'?'✓ сервер принял':'× сервер отклонил'
const reasonLabel=value=>({accepted:'Действие выполнено.',invalid_transition:'Это событие недоступно в текущем состоянии.',invalid_target:'Этот этап нельзя выбрать из текущего состояния.',unmet_prerequisites:'Не выполнены обязательные условия перехода.',checkpoint_missing:'Не заполнена контрольная точка следующего этапа.',planning_questions_open:'Готовый план не может содержать открытые критичные вопросы.',planning_questions_missing:'Для черновика укажите блокирующие вопросы.',planning_requires_define_task:'План создаётся и уточняется только через безопасное действие планирования.',stale_revision:'Состояние уже изменилось: обновите данные и повторите попытку.',task_paused:'Задача находится на паузе.',task_done:'Задача уже завершена.',wrong_phase:'Действие недоступно на текущем этапе.',validation_requires_typed_result:'Результат проверки должен явно указывать, остались ли проблемы.',invalid_validation_result:'Признак проблем не соответствует описанию.',pending_approval_missing:'Нет актуального результата, который можно принять.',pending_approval_ambiguous:'Нельзя однозначно определить, какой результат принимается.',consent_ambiguous:'Фраза не является однозначным согласием.',consent_conditional:'Условная формулировка не считается согласием.',consent_negated:'В сообщении есть отрицание.',consent_acceptance_missing:'Нужно явно принять текущий результат.',consent_progress_missing:'Нужно явно попросить продолжить.',transition_intent_ambiguous:'Вопрос или цитата не считаются просьбой перейти.',transition_intent_conditional:'Условная формулировка не запускает переход.',transition_intent_negated:'Отрицание блокирует переход.',transition_intent_missing:'Нет явной просьбы перейти дальше.',structured_decision_missing:'Модель не выбрала безопасный вариант действия.'}[value]||'Сервер зафиксировал результат попытки.')
const requirementLabel=value=>({plan_artifact_missing:'План подготовки не сохранён.',planning_not_ready:'План ещё не готов: закройте критичные вопросы.',plan_not_approved:'План подготовки не подтверждён.',execution_result_missing:'Результат сборов не сохранён.',implementation_not_ready:'Готовность чемодана не подтверждена.',validation_not_passed:'Проверка не подтверждена.',blocking_issues_present:'Остались блокирующие замечания.'}[value]||value)
const actionLabel=value=>({define_task:'Задача и предложенный план',save_current_evidence:'Сохранение результата текущего шага',record_validation_result:'Результат финальной проверки',accept_current_evidence_and_advance:'Ваше согласие и переход дальше',request_transition:'Запрос перехода',pause_task:'Пауза',resume_task:'Продолжение',respond_without_action:'Ответ без изменения состояния',multiple_tool_calls:'Несколько действий'}[value]||value)
const approvalLabel=value=>({plan_approved:'Подтверждение плана подготовки',implementation_ready:'Подтверждение готовности чемодана',validation_passed:'Подтверждение финальной проверки'}[value]||value)
watch(()=>state.value?.active_session?.messages?.length,()=>nextTick(scrollBottom));watch(()=>controls.provider,provider=>{if(provider==='openrouter')controls.model='openrouter/free';else if(!['deepseek-flash','deepseek-v4-pro'].includes(controls.model))controls.model='deepseek-flash'});onMounted(async()=>{try{const saved=Number(localStorage.getItem(PANEL_STORAGE_KEY));if(Number.isFinite(saved)&&saved>0)statePanelWidth.value=saved}catch{ /* Use the default width. */ }window.addEventListener('resize',handleViewportResize);await nextTick();updatePanelBounds();try{sync(await api('/api/state'))}catch(e){error.value=e.message}});onBeforeUnmount(()=>{window.removeEventListener('resize',handleViewportResize);document.body.classList.remove('resizing-state-panel')})
</script>
